#!/usr/bin/env node
/**
 * Build script: sync the frontend source into backend/dist (the folder the
 * Express server actually serves).
 *
 *   node tools/build.js
 *
 * Keeps backend/dist/ in lockstep with frontend/ so the deployed app can never
 * serve a stale copy. Icons are generated by tools/make_icons.py (Python/PIL);
 * this script copies whatever is already in frontend/ and warns if an icon is
 * missing.
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.join(__dirname, '..');
const SRC = path.join(ROOT, 'frontend');
const DEST = path.join(ROOT, 'backend', 'dist');

const REQUIRED_ICONS = [
  'icon-192.png',
  'icon-512.png',
  'icon-maskable-512.png',
  'apple-touch-icon.png',
  'favicon-32.png',
  'favicon.ico',
];

function copyTree(src, dest) {
  fs.mkdirSync(dest, { recursive: true });
  let count = 0;
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const s = path.join(src, entry.name);
    const d = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      count += copyTree(s, d);
    } else {
      fs.copyFileSync(s, d);
      count++;
    }
  }
  return count;
}

function cleanDir(dir) {
  if (!fs.existsSync(dir)) return;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    fs.rmSync(path.join(dir, entry.name), { recursive: true, force: true });
  }
}

if (!fs.existsSync(SRC)) {
  console.error(`[build] missing frontend source: ${SRC}`);
  process.exit(1);
}

// Wipe the destination first so removed/renamed source files can't linger
// and keep being served.
cleanDir(DEST);
const n = copyTree(SRC, DEST);
console.log(`[build] copied ${n} file(s) from frontend/ -> backend/dist/`);

const missing = REQUIRED_ICONS.filter((f) => !fs.existsSync(path.join(DEST, f)));
if (missing.length) {
  console.warn(`[build] WARNING missing icon(s): ${missing.join(', ')}`);
  console.warn('[build] run: python tools/make_icons.py');
}

const html = fs.readFileSync(path.join(DEST, 'index.html'), 'utf8');
if (/https?:\/\/(cdn|unpkg|cdnjs)/i.test(html)) {
  console.warn('[build] WARNING: a CDN reference is still present in index.html');
}

console.log('[build] done');
